    23	class BinPackingData {
    24	public:
    25	  // ---------------------------- input data -----------------------------
    26	  int n;                                 // number of items
    27	  long long C;                           // capacity of each bin
    28	  int k;                                 // number of conflict classes
    29	  std::vector<long long> size;           // size[i], 0 < size[i] <= C, i=1..n
    30	  std::vector<std::vector<int> > cls;    // cls[t] = items of the class S_t
    31	  std::vector<std::vector<int> > classes_of; // classes_of[i] = classes containing i
    32	
    33	  // ----------------- parameters of the run (set by main) ----------------
    34	  unsigned seed;                         // seed of the random number generator
    35	
    36	  // ------------------- best solution found so far -----------------------
    37	  // best_value is the number of bins of best_solution; it is INT_MAX-like
    38	  // (n+1) while no solution is known. best_solution[b] is the list of items
    39	  // packed in the bin b. lower_bound is a valid lower bound on the optimum.
    40	  int best_value;
    41	  std::vector<std::vector<int> > best_solution;
    42	  int lower_bound;
